module FetchUnit(
  input          clock,
                 reset,
  output [31:0]  io_decodeStage_data_inst,
  output         io_decodeStage_data_valid,
  output [31:0]  io_decodeStage_data_pc,
  output         io_decodeStage_data_predicted_taken,
  output [31:0]  io_decodeStage_data_predicted_target,
  input          io_icache_resp_valid,
  input  [255:0] io_icache_resp_bits_data,
  input  [31:0]  io_icache_resp_bits_addr,
  input          io_signal_fetchUnitSignal_allow_to_go,
                 io_signal_branchControl_branch,
  input  [31:0]  io_signal_branchControl_target,
  input          io_icache_req_ready,
  output         io_icache_req_valid,
  output [31:0]  io_icache_req_bits_addr,
  input          io_bpu_feedback_valid,
  input  [31:0]  io_bpu_feedback_pc,
  input          io_bpu_feedback_actual_taken,
  input  [31:0]  io_bpu_feedback_actual_target,
  input          io_bpu_feedback_mispredicted
);

  wire             _bpu_io_prediction_predicted_taken;
  wire [31:0]      _bpu_io_prediction_predicted_target;
  wire             _bpu_io_flush_req;
  reg  [31:0]      pc;
  reg  [31:0]      reqPC;
  reg  [1:0]       state;
  reg  [31:0]      ifid_reg_inst;
  reg              ifid_reg_valid;
  reg  [31:0]      ifid_reg_pc;
  reg              ifid_reg_predicted_taken;
  reg  [31:0]      ifid_reg_predicted_target;
  wire             branch = io_signal_branchControl_branch | _bpu_io_flush_req;
  wire [31:0]      _next_pc_T = pc + 32'h4;
  reg              canStart_REG;
  reg              io_canStart_REG;
  wire             io_canStart =
    ~(|state) & ~(~io_signal_fetchUnitSignal_allow_to_go | ifid_reg_valid)
    & io_canStart_REG;
  wire             _GEN = state == 2'h1;
  wire [7:0][31:0] _GEN_0 =
    {{io_icache_resp_bits_data[255:224]},
     {io_icache_resp_bits_data[223:192]},
     {io_icache_resp_bits_data[191:160]},
     {io_icache_resp_bits_data[159:128]},
     {io_icache_resp_bits_data[127:96]},
     {io_icache_resp_bits_data[95:64]},
     {io_icache_resp_bits_data[63:32]},
     {io_icache_resp_bits_data[31:0]}};
  wire [31:0]      inst = _GEN_0[reqPC[4:2]];
  wire             _GEN_1 = io_icache_resp_valid & io_icache_resp_bits_addr == reqPC;
  wire             _GEN_2 = _GEN & _GEN_1 & io_signal_fetchUnitSignal_allow_to_go;
  wire             _GEN_3 = (|state) & _GEN_2;
  wire             _GEN_4 = _GEN & _GEN_1;
  wire             _GEN_5 = ifid_reg_valid & io_signal_fetchUnitSignal_allow_to_go;
  always @(posedge clock) begin
    automatic logic canStart;
    automatic logic _GEN_6;
    canStart = canStart_REG & ~reset;
    _GEN_6 = io_canStart & io_icache_req_ready;
    if (reset) begin
      pc <= 32'h80000000;
      state <= 2'h0;
      ifid_reg_inst <= 32'h0;
      ifid_reg_valid <= 1'h0;
      ifid_reg_pc <= 32'h0;
      ifid_reg_predicted_taken <= 1'h0;
      ifid_reg_predicted_target <= 32'h0;
    end
    else begin
      automatic logic _GEN_7;
      _GEN_7 = branch | ~(|state) | ~_GEN_4 | io_signal_fetchUnitSignal_allow_to_go;
      if (branch) begin
        if (_bpu_io_flush_req) begin
          if (io_bpu_feedback_valid)
            pc <= io_bpu_feedback_actual_target;
          else
            pc <= _next_pc_T;
        end
        else
          pc <= io_signal_branchControl_target;
        state <= 2'h0;
      end
      else if (|state) begin
        if (_GEN_4)
          state <= 2'h0;
      end
      else if (_GEN_6) begin
        if (_bpu_io_prediction_predicted_taken)
          pc <= _bpu_io_prediction_predicted_target;
        else
          pc <= _next_pc_T;
        state <= 2'h1;
      end
      else if (canStart & pc == 32'h0)
        pc <= 32'h80000000;
      if (_GEN_7) begin
      end
      else
        ifid_reg_inst <= inst;
      ifid_reg_valid <=
        ~(branch | _GEN_5)
        & ((|state) & _GEN_4 & ~io_signal_fetchUnitSignal_allow_to_go | ifid_reg_valid);
      if (_GEN_7) begin
      end
      else begin
        ifid_reg_pc <= reqPC;
        ifid_reg_predicted_taken <= _bpu_io_prediction_predicted_taken;
        ifid_reg_predicted_target <= _bpu_io_prediction_predicted_target;
      end
    end
    if (branch | ~(~(|state) & _GEN_6)) begin
    end
    else
      reqPC <= pc;
    canStart_REG <= ~reset;
    io_canStart_REG <= canStart;
  end // always @(posedge)
  `ifdef ENABLE_INITIAL_REG_
    `ifdef FIRRTL_BEFORE_INITIAL
      `FIRRTL_BEFORE_INITIAL
    `endif // FIRRTL_BEFORE_INITIAL
    initial begin
      automatic logic [31:0] _RANDOM[0:5];
      `ifdef INIT_RANDOM_PROLOG_
        `INIT_RANDOM_PROLOG_
      `endif // INIT_RANDOM_PROLOG_
      `ifdef RANDOMIZE_REG_INIT
        for (logic [2:0] i = 3'h0; i < 3'h6; i += 3'h1) begin
          _RANDOM[i] = `RANDOM;
        end
        pc = _RANDOM[3'h0];
        reqPC = _RANDOM[3'h1];
        state = _RANDOM[3'h2][1:0];
        ifid_reg_inst = {_RANDOM[3'h2][31:2], _RANDOM[3'h3][1:0]};
        ifid_reg_valid = _RANDOM[3'h3][2];
        ifid_reg_pc = {_RANDOM[3'h3][31:3], _RANDOM[3'h4][2:0]};
        ifid_reg_predicted_taken = _RANDOM[3'h4][3];
        ifid_reg_predicted_target = {_RANDOM[3'h4][31:4], _RANDOM[3'h5][3:0]};
        canStart_REG = _RANDOM[3'h5][4];
        io_canStart_REG = _RANDOM[3'h5][5];
      `endif // RANDOMIZE_REG_INIT
    end // initial
    `ifdef FIRRTL_AFTER_INITIAL
      `FIRRTL_AFTER_INITIAL
    `endif // FIRRTL_AFTER_INITIAL
  `endif // ENABLE_INITIAL_REG_
  Bpu bpu (
    .clock                          (clock),
    .reset                          (reset),
    .io_pc_in                       (pc),
    .io_prediction_predicted_taken  (_bpu_io_prediction_predicted_taken),
    .io_prediction_predicted_target (_bpu_io_prediction_predicted_target),
    .io_feedback_valid              (io_bpu_feedback_valid),
    .io_feedback_pc                 (io_bpu_feedback_pc),
    .io_feedback_actual_taken       (io_bpu_feedback_actual_taken),
    .io_feedback_actual_target      (io_bpu_feedback_actual_target),
    .io_feedback_mispredicted       (io_bpu_feedback_mispredicted),
    .io_flush_req                   (_bpu_io_flush_req)
  );
  assign io_decodeStage_data_inst =
    branch ? 32'h0 : _GEN_5 ? ifid_reg_inst : _GEN_3 ? inst : 32'h0;
  assign io_decodeStage_data_valid =
    ~branch
    & (_GEN_5
         ? ifid_reg_valid
         : (|state) & _GEN_4 & io_signal_fetchUnitSignal_allow_to_go);
  assign io_decodeStage_data_pc =
    branch ? 32'h0 : _GEN_5 ? ifid_reg_pc : _GEN_3 ? reqPC : 32'h0;
  assign io_decodeStage_data_predicted_taken =
    ~branch
    & (_GEN_5
         ? ifid_reg_predicted_taken
         : (|state) & _GEN_2 & _bpu_io_prediction_predicted_taken);
  assign io_decodeStage_data_predicted_target =
    branch
      ? 32'h0
      : _GEN_5
          ? ifid_reg_predicted_target
          : _GEN_3 ? _bpu_io_prediction_predicted_target : 32'h0;
  assign io_icache_req_valid = branch | io_canStart;
  assign io_icache_req_bits_addr =
    branch
      ? (_bpu_io_flush_req
           ? (io_bpu_feedback_valid ? io_bpu_feedback_actual_target : _next_pc_T)
           : io_signal_branchControl_target)
      : pc;
endmodule

module DecodeStage(
  input         clock,
                reset,
  input  [31:0] io_fetchUnit_data_inst,
  input         io_fetchUnit_data_valid,
  input  [31:0] io_fetchUnit_data_pc,
  input         io_fetchUnit_data_predicted_taken,
  input  [31:0] io_fetchUnit_data_predicted_target,
  input         io_controlSignal_fetchUnitSignal_allow_to_go,
                io_controlSignal_fetchUnitSignal_do_flush,
  output [31:0] io_decodeUnit_data_inst,
  output        io_decodeUnit_data_valid,
  output [31:0] io_decodeUnit_data_pc,
  output        io_decodeUnit_data_predicted_taken,
  output [31:0] io_decodeUnit_data_predicted_target
);

  reg [31:0] data_inst;
  reg        data_valid;
  reg [31:0] data_pc;
  reg        data_predicted_taken;
  reg [31:0] data_predicted_target;
  always @(posedge clock) begin
    if (reset) begin
      data_inst <= 32'h0;
      data_valid <= 1'h0;
      data_pc <= 32'h0;
      data_predicted_taken <= 1'h0;
      data_predicted_target <= 32'h0;
    end
    else begin
      if (io_controlSignal_fetchUnitSignal_do_flush) begin
        data_inst <= 32'h0;
        data_pc <= 32'h0;
        data_predicted_target <= 32'h0;
      end
      else if (io_controlSignal_fetchUnitSignal_allow_to_go) begin
        data_inst <= io_fetchUnit_data_inst;
        data_pc <= io_fetchUnit_data_pc;
        data_predicted_target <= io_fetchUnit_data_predicted_target;
      end
      data_valid <=
        ~io_controlSignal_fetchUnitSignal_do_flush
        & (io_controlSignal_fetchUnitSignal_allow_to_go
             ? io_fetchUnit_data_valid
             : data_valid);
      data_predicted_taken <=
        ~io_controlSignal_fetchUnitSignal_do_flush
        & (io_controlSignal_fetchUnitSignal_allow_to_go
             ? io_fetchUnit_data_predicted_taken
             : data_predicted_taken);
    end
  end // always @(posedge)
  `ifdef ENABLE_INITIAL_REG_
    `ifdef FIRRTL_BEFORE_INITIAL
      `FIRRTL_BEFORE_INITIAL
    `endif // FIRRTL_BEFORE_INITIAL
    initial begin
      automatic logic [31:0] _RANDOM[0:3];
      `ifdef INIT_RANDOM_PROLOG_
        `INIT_RANDOM_PROLOG_
      `endif // INIT_RANDOM_PROLOG_
      `ifdef RANDOMIZE_REG_INIT
        for (logic [2:0] i = 3'h0; i < 3'h4; i += 3'h1) begin
          _RANDOM[i[1:0]] = `RANDOM;
        end
        data_inst = _RANDOM[2'h0];
        data_valid = _RANDOM[2'h1][0];
        data_pc = {_RANDOM[2'h1][31:1], _RANDOM[2'h2][0]};
        data_predicted_taken = _RANDOM[2'h2][1];
        data_predicted_target = {_RANDOM[2'h2][31:2], _RANDOM[2'h3][1:0]};
      `endif // RANDOMIZE_REG_INIT
    end // initial
    `ifdef FIRRTL_AFTER_INITIAL
      `FIRRTL_AFTER_INITIAL
    `endif // FIRRTL_AFTER_INITIAL
  `endif // ENABLE_INITIAL_REG_
  assign io_decodeUnit_data_inst = data_inst;
  assign io_decodeUnit_data_valid = data_valid;
  assign io_decodeUnit_data_pc = data_pc;
  assign io_decodeUnit_data_predicted_taken = data_predicted_taken;
  assign io_decodeUnit_data_predicted_target = data_predicted_target;
endmodule

module DecodeUnit(
  input         clock,
                reset,
  input  [31:0] io_decodeStage_data_inst,
  input         io_decodeStage_data_valid,
  input  [31:0] io_decodeStage_data_pc,
  input         io_decodeStage_data_predicted_taken,
  input  [31:0] io_decodeStage_data_predicted_target,
  output [4:0]  io_regfile_src1_raddr,
  input  [31:0] io_regfile_src1_rdata,
  output [4:0]  io_regfile_src2_raddr,
  input  [31:0] io_regfile_src2_rdata,
  input         io_bypassData_src1_bypass,
                io_bypassData_src2_bypass,
  input  [31:0] io_bypassData_src1_data,
                io_bypassData_src2_data,
  output [31:0] io_executeStage_data_pc,
                io_executeStage_data_info_instr,
  output        io_executeStage_data_info_bpu_pred_predicted_taken,
  output [31:0] io_executeStage_data_info_bpu_pred_predicted_target,
  output        io_executeStage_data_info_valid,
  output [4:0]  io_executeStage_data_info_op,
  output        io_executeStage_data_info_reg_wen,
  output [4:0]  io_executeStage_data_info_reg_waddr,
  output [31:0] io_executeStage_data_info_imm,
  output [2:0]  io_executeStage_data_info_fusel,
  output [31:0] io_executeStage_data_src_info_src1_data,
                io_executeStage_data_src_info_src2_data,
  output [4:0]  io_registerInfo_src1_raddr,
                io_registerInfo_src2_raddr,
  output        io_registerInfo_src1_ren,
                io_registerInfo_src2_ren
);

  wire        _GEN = io_decodeStage_data_inst[31:25] == 7'hA;
  wire        _GEN_0 = io_decodeStage_data_inst[31:25] == 7'hE;
  wire        _GEN_1 = io_decodeStage_data_inst[31:22] == 10'hA;
  wire        _GEN_2 = io_decodeStage_data_inst[31:15] == 17'h20;
  wire        _GEN_3 = io_decodeStage_data_inst[31:22] == 10'hF;
  wire        _GEN_4 = io_decodeStage_data_inst[31:15] == 17'h2B;
  wire        _GEN_5 = io_decodeStage_data_inst[31:15] == 17'h81;
  wire        _GEN_6 = io_decodeStage_data_inst[31:15] == 17'h89;
  wire        _GEN_7 = io_decodeStage_data_inst[31:22] == 10'hE;
  wire        _GEN_8 = io_decodeStage_data_inst[31:15] == 17'h2A;
  wire        _GEN_9 = io_decodeStage_data_inst[31:22] == 10'hD;
  wire        _GEN_10 = io_decodeStage_data_inst[31:15] == 17'h29;
  wire        _GEN_11 = io_decodeStage_data_inst[31:15] == 17'h22;
  wire        _GEN_12 = io_decodeStage_data_inst[31:15] == 17'h38;
  wire        _GEN_13 = io_decodeStage_data_inst[31:22] == 10'hA0;
  wire        _GEN_14 = io_decodeStage_data_inst[31:22] == 10'hA2;
  wire        _GEN_15 = io_decodeStage_data_inst[31:22] == 10'hA4;
  wire        _GEN_16 = io_decodeStage_data_inst[31:22] == 10'hA6;
  wire        _GEN_17 = io_decodeStage_data_inst[31:26] == 6'h16;
  wire        _GEN_18 = io_decodeStage_data_inst[31:26] == 6'h17;
  wire        _GEN_19 = io_decodeStage_data_inst[31:26] == 6'h14;
  wire        _GEN_20 = io_decodeStage_data_inst[31:26] == 6'h15;
  wire        _GEN_21 = io_decodeStage_data_inst[31:26] == 6'h13;
  wire        _GEN_22 = _GEN_19 | _GEN_20 | _GEN_21;
  wire        _GEN_23 = _GEN_15 | _GEN_16;
  wire [2:0]  instrType =
    _GEN | _GEN_0
      ? 3'h6
      : _GEN_1
          ? 3'h4
          : _GEN_2
              ? 3'h5
              : _GEN_3
                  ? 3'h4
                  : _GEN_4
                      ? 3'h5
                      : _GEN_5 | _GEN_6 | _GEN_7
                          ? 3'h4
                          : _GEN_8
                              ? 3'h5
                              : _GEN_9
                                  ? 3'h4
                                  : _GEN_10 | _GEN_11 | _GEN_12
                                      ? 3'h5
                                      : _GEN_13 | _GEN_14
                                          ? 3'h4
                                          : _GEN_23
                                              ? 3'h2
                                              : _GEN_17 | _GEN_18 ? 3'h1 : {3{_GEN_22}};
  wire [3:0]  fuOpType =
    _GEN | _GEN_0 | _GEN_1 | _GEN_2
      ? 4'h0
      : _GEN_3 | _GEN_4
          ? 4'h4
          : _GEN_5
              ? 4'h9
              : _GEN_6
                  ? 4'h5
                  : _GEN_7 | _GEN_8
                      ? 4'h7
                      : _GEN_9 | _GEN_10
                          ? 4'h8
                          : _GEN_11
                              ? 4'h1
                              : _GEN_12 | _GEN_13
                                  ? 4'h0
                                  : _GEN_14
                                      ? 4'h2
                                      : _GEN_15
                                          ? 4'h8
                                          : _GEN_16
                                              ? 4'hA
                                              : _GEN_17
                                                  ? 4'h0
                                                  : _GEN_18
                                                      ? 4'h1
                                                      : _GEN_19
                                                          ? 4'h8
                                                          : _GEN_20
                                                              ? 4'hA
                                                              : _GEN_21 ? 4'hB : 4'h0;
  wire [9:0]  _imm_j_T_2 = fuOpType == 4'hB ? 10'h0 : io_decodeStage_data_inst[9:0];
  wire        isR = instrType == 3'h5;
  wire        isI = instrType == 3'h4;
  wire        isU = instrType == 3'h6;
  wire        isS = instrType == 3'h2;
  wire        isB = instrType == 3'h1;
  wire [31:0] imm =
    (isI
       ? {io_decodeStage_data_inst[24] ? 20'h0 : {20{io_decodeStage_data_inst[21]}},
          io_decodeStage_data_inst[21:10]}
       : 32'h0)
    | (isS
         ? {{20{io_decodeStage_data_inst[21]}}, io_decodeStage_data_inst[21:10]}
         : 32'h0)
    | (isB
         ? {{14{io_decodeStage_data_inst[25]}}, io_decodeStage_data_inst[25:10], 2'h0}
         : 32'h0) | (isU ? {io_decodeStage_data_inst[24:5], 12'h0} : 32'h0)
    | ((&instrType)
         ? {{4{_imm_j_T_2[9]}}, _imm_j_T_2, io_decodeStage_data_inst[25:10], 2'h0}
         : 32'h0);
  wire [4:0]  reg_waddr =
    (isR | isI | isU ? io_decodeStage_data_inst[4:0] : 5'h0)
    | ((&instrType) ? (fuOpType == 4'hA ? 5'h1 : io_decodeStage_data_inst[4:0]) : 5'h0);
  wire [4:0]  src2_raddr =
    isR
      ? io_decodeStage_data_inst[14:10]
      : isS | isB ? io_decodeStage_data_inst[4:0] : 5'h0;
  wire        _src1_ren_T = isR | isI;
  wire        reg_wen = _src1_ren_T | isU | (&instrType) & fuOpType != 4'h8;
  wire        src1_ren = _src1_ren_T | isS | isB | (&instrType);
  wire        src2_ren = isR | isS | isB;
  `ifndef SYNTHESIS
    always @(posedge clock) begin
      if ((`PRINTF_COND_) & io_decodeStage_data_valid & ~reset) begin
        $fwrite(32'h80000002, "[DecodeUnit] Decoding: PC=0x%x, Inst=0x%x\n",
                io_decodeStage_data_pc, io_decodeStage_data_inst);
        $fwrite(32'h80000002, "  src1_raddr=%d, src2_raddr=%d, reg_waddr=%d\n",
                io_decodeStage_data_inst[9:5], src2_raddr, reg_waddr);
        $fwrite(32'h80000002, "  src1_ren=%d, src2_ren=%d, reg_wen=%d\n", src1_ren,
                src2_ren, reg_wen);
      end
    end // always @(posedge)
  `endif // not def SYNTHESIS
  assign io_regfile_src1_raddr = src1_ren ? io_decodeStage_data_inst[9:5] : 5'h0;
  assign io_regfile_src2_raddr = src2_ren ? src2_raddr : 5'h0;
  assign io_executeStage_data_pc = io_decodeStage_data_pc;
  assign io_executeStage_data_info_instr =
    (|instrType) ? io_decodeStage_data_inst : 32'h2800000;
  assign io_executeStage_data_info_bpu_pred_predicted_taken =
    io_decodeStage_data_predicted_taken;
  assign io_executeStage_data_info_bpu_pred_predicted_target =
    io_decodeStage_data_predicted_target;
  assign io_executeStage_data_info_valid = io_decodeStage_data_valid & (|instrType);
  assign io_executeStage_data_info_op = {1'h0, fuOpType};
  assign io_executeStage_data_info_reg_wen =
    reg_wen & io_decodeStage_data_valid & (|instrType);
  assign io_executeStage_data_info_reg_waddr = reg_waddr;
  assign io_executeStage_data_info_imm = imm;
  assign io_executeStage_data_info_fusel =
    {1'h0,
     _GEN | _GEN_0 | _GEN_1 | _GEN_2 | _GEN_3 | _GEN_4 | _GEN_5 | _GEN_6 | _GEN_7 | _GEN_8
     | _GEN_9 | _GEN_10 | _GEN_11
       ? 2'h0
       : _GEN_12
           ? 2'h1
           : _GEN_13 | _GEN_14 | _GEN_23 ? 2'h2 : {2{_GEN_17 | _GEN_18 | _GEN_22}}};
  assign io_executeStage_data_src_info_src1_data =
    (src1_ren
       ? (io_bypassData_src1_bypass ? io_bypassData_src1_data : io_regfile_src1_rdata)
       : 32'h0)
    | (~src1_ren & io_decodeStage_data_inst[31:25] != 7'hA
         ? io_decodeStage_data_pc
         : 32'h0);
  assign io_executeStage_data_src_info_src2_data =
    src2_ren
      ? (io_bypassData_src2_bypass ? io_bypassData_src2_data : io_regfile_src2_rdata)
      : imm;
  assign io_registerInfo_src1_raddr = io_decodeStage_data_inst[9:5];
  assign io_registerInfo_src2_raddr = src2_raddr;
  assign io_registerInfo_src1_ren = src1_ren;
  assign io_registerInfo_src2_ren = src2_ren;
endmodule

