  output [4:0]  io_executeUnit_data_info_reg_waddr,
  output [31:0] io_executeUnit_data_info_imm,
  output [2:0]  io_executeUnit_data_info_fusel,
  output [31:0] io_executeUnit_data_src_info_src1_data,
                io_executeUnit_data_src_info_src2_data
);

  reg [1:0]  state;
  reg [31:0] data_pc;
  reg [31:0] data_info_instr;
  reg        data_info_bpu_pred_predicted_taken;
  reg [31:0] data_info_bpu_pred_predicted_target;
  reg        data_info_valid;
  reg [4:0]  data_info_op;
  reg        data_info_reg_wen;
  reg [4:0]  data_info_reg_waddr;
  reg [31:0] data_info_imm;
  reg [2:0]  data_info_fusel;
  reg [31:0] data_src_info_src1_data;
  reg [31:0] data_src_info_src2_data;
  always @(posedge clock) begin
    if (reset) begin
      state <= 2'h0;
      data_pc <= 32'h0;
      data_info_instr <= 32'h0;
      data_info_bpu_pred_predicted_taken <= 1'h0;
      data_info_bpu_pred_predicted_target <= 32'h0;
      data_info_valid <= 1'h0;
      data_info_op <= 5'h0;
      data_info_reg_wen <= 1'h0;
      data_info_reg_waddr <= 5'h0;
      data_info_imm <= 32'h0;
      data_info_fusel <= 3'h0;
      data_src_info_src1_data <= 32'h0;
      data_src_info_src2_data <= 32'h0;
    end
    else begin
      automatic logic            _GEN;
      automatic logic [3:0][1:0] _GEN_0;
      _GEN = io_controlSignal_decodeUnitSignal_allow_to_go & io_ready;
      _GEN_0 =
        {{state},
         {2'h0},
         {io_controlSignal_decodeUnitSignal_do_flush ? 2'h2 : 2'h1},
         {_GEN ? 2'h1 : state}};
      state <= _GEN_0[state];
      if (state == 2'h0) begin
        if (_GEN) begin
          data_pc <= io_decodeUnit_data_pc;
          data_info_instr <= io_decodeUnit_data_info_instr;
          data_info_bpu_pred_predicted_taken <=
            io_decodeUnit_data_info_bpu_pred_predicted_taken;
          data_info_bpu_pred_predicted_target <=
            io_decodeUnit_data_info_bpu_pred_predicted_target;
          data_info_valid <= io_decodeUnit_data_info_valid;
          data_info_op <= io_decodeUnit_data_info_op;
          data_info_reg_wen <= io_decodeUnit_data_info_reg_wen;
          data_info_reg_waddr <= io_decodeUnit_data_info_reg_waddr;
          data_info_imm <= io_decodeUnit_data_info_imm;
          data_info_fusel <= io_decodeUnit_data_info_fusel;
          data_src_info_src1_data <= io_decodeUnit_data_src_info_src1_data;
          data_src_info_src2_data <= io_decodeUnit_data_src_info_src2_data;
        end
      end
      else if (state == 2'h1) begin
        if (io_controlSignal_decodeUnitSignal_do_flush) begin
          data_pc <= 32'h0;
          data_info_instr <= 32'h0;
          data_info_bpu_pred_predicted_target <= 32'h0;
          data_info_op <= 5'h0;
          data_info_reg_waddr <= 5'h0;
          data_info_imm <= 32'h0;
          data_info_fusel <= 3'h0;
          data_src_info_src1_data <= 32'h0;
          data_src_info_src2_data <= 32'h0;
        end
        else if (_GEN) begin
          data_pc <= io_decodeUnit_data_pc;
          data_info_instr <= io_decodeUnit_data_info_instr;
          data_info_bpu_pred_predicted_target <=
            io_decodeUnit_data_info_bpu_pred_predicted_target;
          data_info_op <= io_decodeUnit_data_info_op;
          data_info_reg_waddr <= io_decodeUnit_data_info_reg_waddr;
          data_info_imm <= io_decodeUnit_data_info_imm;
          data_info_fusel <= io_decodeUnit_data_info_fusel;
          data_src_info_src1_data <= io_decodeUnit_data_src_info_src1_data;
          data_src_info_src2_data <= io_decodeUnit_data_src_info_src2_data;
        end
        data_info_bpu_pred_predicted_taken <=
          ~io_controlSignal_decodeUnitSignal_do_flush
          & (_GEN
               ? io_decodeUnit_data_info_bpu_pred_predicted_taken
               : data_info_bpu_pred_predicted_taken);
        data_info_valid <=
          ~io_controlSignal_decodeUnitSignal_do_flush
          & (_GEN ? io_decodeUnit_data_info_valid : data_info_valid);
        data_info_reg_wen <=
          ~io_controlSignal_decodeUnitSignal_do_flush
          & (_GEN ? io_decodeUnit_data_info_reg_wen : data_info_reg_wen);
      end
    end
  end // always @(posedge)
  `ifdef ENABLE_INITIAL_REG_
    `ifdef FIRRTL_BEFORE_INITIAL
      `FIRRTL_BEFORE_INITIAL
    `endif // FIRRTL_BEFORE_INITIAL
    initial begin
      automatic logic [31:0] _RANDOM[0:92];
      `ifdef INIT_RANDOM_PROLOG_
        `INIT_RANDOM_PROLOG_
      `endif // INIT_RANDOM_PROLOG_
      `ifdef RANDOMIZE_REG_INIT
        for (logic [6:0] i = 7'h0; i < 7'h5D; i += 7'h1) begin
          _RANDOM[i] = `RANDOM;
        end
        state = _RANDOM[7'h0][1:0];
        data_pc = {_RANDOM[7'h0][31:2], _RANDOM[7'h1][1:0]};
        data_info_instr = {_RANDOM[7'h1][31:2], _RANDOM[7'h2][1:0]};
        data_info_bpu_pred_predicted_taken = _RANDOM[7'h2][2];
        data_info_bpu_pred_predicted_target = {_RANDOM[7'h2][31:3], _RANDOM[7'h3][2:0]};
        data_info_valid = _RANDOM[7'h3][3];
        data_info_op = _RANDOM[7'h3][18:14];
        data_info_reg_wen = _RANDOM[7'h3][19];
        data_info_reg_waddr = _RANDOM[7'h3][24:20];
        data_info_imm = {_RANDOM[7'h3][31:25], _RANDOM[7'h4][24:0]};
        data_info_fusel = _RANDOM[7'h4][29:27];
        data_src_info_src1_data = _RANDOM[7'h5B];
        data_src_info_src2_data = _RANDOM[7'h5C];
      `endif // RANDOMIZE_REG_INIT
    end // initial
    `ifdef FIRRTL_AFTER_INITIAL
      `FIRRTL_AFTER_INITIAL
    `endif // FIRRTL_AFTER_INITIAL
  `endif // ENABLE_INITIAL_REG_
  assign io_executeUnit_data_pc = data_pc;
  assign io_executeUnit_data_info_instr = data_info_instr;
  assign io_executeUnit_data_info_bpu_pred_predicted_taken =
    data_info_bpu_pred_predicted_taken;
  assign io_executeUnit_data_info_bpu_pred_predicted_target =
    data_info_bpu_pred_predicted_target;
  assign io_executeUnit_data_info_valid = data_info_valid;
  assign io_executeUnit_data_info_op = data_info_op;
  assign io_executeUnit_data_info_reg_wen = data_info_reg_wen;
  assign io_executeUnit_data_info_reg_waddr = data_info_reg_waddr;
  assign io_executeUnit_data_info_imm = data_info_imm;
  assign io_executeUnit_data_info_fusel = data_info_fusel;
  assign io_executeUnit_data_src_info_src1_data = data_src_info_src1_data;
  assign io_executeUnit_data_src_info_src2_data = data_src_info_src2_data;
endmodule

module Alu(
  input         io_info_valid,
  input  [4:0]  io_info_op,
  input  [31:0] io_src_info_src1_data,
                io_src_info_src2_data,
  output [31:0] io_result,
  output        io_valid
);

  wire [62:0] _sll_result_T =
    {31'h0, io_src_info_src1_data} << io_src_info_src2_data[4:0];
  assign io_result =
    io_info_op == 5'h5
      ? io_src_info_src1_data >> io_src_info_src2_data[4:0]
      : io_info_op == 5'h9
          ? _sll_result_T[31:0]
          : io_info_op == 5'h4
              ? io_src_info_src1_data ^ io_src_info_src2_data
              : io_info_op == 5'h7
                  ? io_src_info_src1_data | io_src_info_src2_data
                  : io_info_op == 5'h8
                      ? io_src_info_src1_data & io_src_info_src2_data
                      : io_info_op == 5'h1
                          ? io_src_info_src1_data - io_src_info_src2_data
                          : io_info_op == 5'h0
                              ? io_src_info_src1_data + io_src_info_src2_data
                              : 32'h0;
  assign io_valid = io_info_valid;
endmodule

module Mdu(
  input         clock,
                reset,
                io_info_valid,
  input  [4:0]  io_info_op,
  input  [2:0]  io_info_fusel,
  input  [31:0] io_src_info_src1_data,
                io_src_info_src2_data,
  output [31:0] io_result,
  output        io_valid,
                io_ready
);

  wire        isMulW = io_info_valid & io_info_fusel == 3'h1 & io_info_op == 5'h0;
  reg  [31:0] stage1_result;
  reg  [31:0] stage2_result;
  reg         stage1_valid;
  reg         stage2_valid;
  reg         busy;
  always @(posedge clock) begin
    if (reset) begin
      stage1_result <= 32'h0;
      stage2_result <= 32'h0;
      stage1_valid <= 1'h0;
      stage2_valid <= 1'h0;
      busy <= 1'h0;
    end
    else begin
      automatic logic _GEN;
      _GEN = isMulW & ~busy;
      if (_GEN)
        stage1_result <= io_src_info_src1_data * io_src_info_src2_data;
      stage2_result <= stage1_result;
      stage1_valid <= _GEN | ~(~isMulW & ~busy) & stage1_valid;
      stage2_valid <= stage1_valid;
      busy <= _GEN | ~stage2_valid & busy;
    end
  end // always @(posedge)
  `ifdef ENABLE_INITIAL_REG_
    `ifdef FIRRTL_BEFORE_INITIAL
      `FIRRTL_BEFORE_INITIAL
    `endif // FIRRTL_BEFORE_INITIAL
    initial begin
      automatic logic [31:0] _RANDOM[0:2];
      `ifdef INIT_RANDOM_PROLOG_
        `INIT_RANDOM_PROLOG_
      `endif // INIT_RANDOM_PROLOG_
      `ifdef RANDOMIZE_REG_INIT
        for (logic [1:0] i = 2'h0; i < 2'h3; i += 2'h1) begin
          _RANDOM[i] = `RANDOM;
        end
        stage1_result = _RANDOM[2'h0];
        stage2_result = _RANDOM[2'h1];
        stage1_valid = _RANDOM[2'h2][0];
        stage2_valid = _RANDOM[2'h2][1];
        busy = _RANDOM[2'h2][2];
      `endif // RANDOMIZE_REG_INIT
    end // initial
    `ifdef FIRRTL_AFTER_INITIAL
      `FIRRTL_AFTER_INITIAL
    `endif // FIRRTL_AFTER_INITIAL
  `endif // ENABLE_INITIAL_REG_
  assign io_result = stage2_result;
  assign io_valid = stage2_valid;
  assign io_ready = ~isMulW | stage2_valid;
endmodule

module WriteBuffer(
  input         clock,
                reset,
  output        io_enq_ready,
  input         io_enq_valid,
  input  [31:0] io_enq_bits_addr,
  input         io_enq_bits_write,
  input  [31:0] io_enq_bits_wdata,
  input  [3:0]  io_enq_bits_wstrb,
  input  [2:0]  io_enq_bits_size,
  input         io_deq_ready,
  output        io_deq_valid,
  output [31:0] io_deq_bits_addr,
  output        io_deq_bits_write,
  output [31:0] io_deq_bits_wdata,
  output [3:0]  io_deq_bits_wstrb,
  output [2:0]  io_deq_bits_size,
  input         io_flush,
  input  [31:0] io_bypassAddr,
  input         io_bypassEnable,
  output        io_bypassHit,
  output [31:0] io_bypassData
);

  reg  [31:0]      buffer_0_req_addr;
  reg              buffer_0_req_write;
  reg  [31:0]      buffer_0_req_wdata;
  reg  [3:0]       buffer_0_req_wstrb;
  reg  [2:0]       buffer_0_req_size;
  reg  [31:0]      buffer_1_req_addr;
  reg              buffer_1_req_write;
  reg  [31:0]      buffer_1_req_wdata;
  reg  [3:0]       buffer_1_req_wstrb;
  reg  [2:0]       buffer_1_req_size;
  reg  [31:0]      buffer_2_req_addr;
  reg              buffer_2_req_write;
  reg  [31:0]      buffer_2_req_wdata;
  reg  [3:0]       buffer_2_req_wstrb;
  reg  [2:0]       buffer_2_req_size;
  reg  [31:0]      buffer_3_req_addr;
  reg              buffer_3_req_write;
  reg  [31:0]      buffer_3_req_wdata;
  reg  [3:0]       buffer_3_req_wstrb;
  reg  [2:0]       buffer_3_req_size;
  reg              valids_0;
  reg              valids_1;
  reg              valids_2;
  reg              valids_3;
  wire             addrMatches_0 =
    buffer_0_req_write & buffer_0_req_addr == io_enq_bits_addr;
  wire             addrMatches_1 =
    buffer_1_req_write & buffer_1_req_addr == io_enq_bits_addr;
  wire             addrMatches_2 =
    buffer_2_req_write & buffer_2_req_addr == io_enq_bits_addr;
  wire             hasMatch =
    addrMatches_0 | addrMatches_1 | addrMatches_2 | buffer_3_req_write
    & buffer_3_req_addr == io_enq_bits_addr;
  wire [1:0]       matchIdx =
    addrMatches_0 ? 2'h0 : addrMatches_1 ? 2'h1 : {1'h1, ~addrMatches_2};
  wire [1:0]       deqIdx = valids_0 ? 2'h0 : valids_1 ? 2'h1 : {1'h1, ~valids_2};
  wire [2:0]       _hasSpace_T_9 =
    {1'h0, {1'h0, valids_0} + {1'h0, valids_1}}
    + {1'h0, {1'h0, valids_2} + {1'h0, valids_3}};
  wire             io_enq_ready_0 = hasMatch | ~(_hasSpace_T_9[2]);
  wire             io_deq_valid_0 = valids_0 | valids_1 | valids_2 | valids_3;
  wire [3:0][31:0] _GEN =
    {{buffer_3_req_addr}, {buffer_2_req_addr}, {buffer_1_req_addr}, {buffer_0_req_addr}};
  wire [3:0]       _GEN_0 =
    {{buffer_3_req_write},
     {buffer_2_req_write},
     {buffer_1_req_write},
     {buffer_0_req_write}};
  wire [3:0][31:0] _GEN_1 =
    {{buffer_3_req_wdata},
     {buffer_2_req_wdata},
     {buffer_1_req_wdata},
     {buffer_0_req_wdata}};
  wire [3:0][3:0]  _GEN_2 =
    {{buffer_3_req_wstrb},
     {buffer_2_req_wstrb},
     {buffer_1_req_wstrb},
     {buffer_0_req_wstrb}};
  wire [3:0][2:0]  _GEN_3 =
    {{buffer_3_req_size}, {buffer_2_req_size}, {buffer_1_req_size}, {buffer_0_req_size}};
  wire             _GEN_4 = io_enq_ready_0 & io_enq_valid;
  wire             bypassMatches_0 =
    io_bypassEnable & buffer_0_req_write & buffer_0_req_addr == io_bypassAddr
    & buffer_0_req_addr[31:22] == 10'h201;
  wire             bypassMatches_1 =
    io_bypassEnable & buffer_1_req_write & buffer_1_req_addr == io_bypassAddr
    & buffer_1_req_addr[31:22] == 10'h201;
  wire             bypassMatches_2 =
    io_bypassEnable & buffer_2_req_write & buffer_2_req_addr == io_bypassAddr
    & buffer_2_req_addr[31:22] == 10'h201;
  wire             bypassMatches_3 =
    io_bypassEnable & buffer_3_req_write & buffer_3_req_addr == io_bypassAddr
    & buffer_3_req_addr[31:22] == 10'h201;
  wire             io_bypassHit_0 =
    bypassMatches_0 | bypassMatches_1 | bypassMatches_2 | bypassMatches_3;
  wire [31:0]      _io_bypassData_T_6 =
    (bypassMatches_0 ? buffer_0_req_wdata : 32'h0)
    | (bypassMatches_1 ? buffer_1_req_wdata : 32'h0)
    | (bypassMatches_2 ? buffer_2_req_wdata : 32'h0)
    | (bypassMatches_3 ? buffer_3_req_wdata : 32'h0);
  `ifndef SYNTHESIS
    always @(posedge clock) begin
      if ((`PRINTF_COND_) & _GEN_4 & hasMatch & ~reset)
        $fwrite(32'h80000002,
                "[WriteBuffer] Write coalescing: addr=0x%x, old_data=0x%x, new_data=0x%x\n",
                io_enq_bits_addr, _GEN_1[matchIdx], io_enq_bits_wdata);
      if ((`PRINTF_COND_) & io_bypassHit_0 & ~reset)
        $fwrite(32'h80000002, "[WriteBuffer] Bypass hit: addr=0x%x, data=0x%x\n",
                io_bypassAddr, _io_bypassData_T_6);
    end // always @(posedge)
  `endif // not def SYNTHESIS
  always @(posedge clock) begin
    if (reset) begin
      buffer_0_req_addr <= 32'h0;
      buffer_0_req_write <= 1'h0;
      buffer_0_req_wdata <= 32'h0;
      buffer_0_req_wstrb <= 4'h0;
      buffer_0_req_size <= 3'h0;
      buffer_1_req_addr <= 32'h0;
      buffer_1_req_write <= 1'h0;
      buffer_1_req_wdata <= 32'h0;
      buffer_1_req_wstrb <= 4'h0;
      buffer_1_req_size <= 3'h0;
      buffer_2_req_addr <= 32'h0;
      buffer_2_req_write <= 1'h0;
